/bin/zsh -lc "/opt/homebrew/bin/python3 -c 'from math import comb; import json; from pathlib import Path; C=lambda n,k:comb(n,k) if 0<=k<=n else 0; T=lambda j,d,i,h:C(2*d,h)*C(2*i-2-h,i)*(C(j+i+1,2*i-1-h)+C(j+i,2*i-1-h)) if i>=2 and 0<=h<=i-2 else 0; fail=[]; count=0
for j in range(2,25):
 for d in range(10):
  for i in range(2,j+2*d+3):
   for h in range(min(2*d,i-2)+1):
    for k in range(min(2*d,i)+1):
     a=T(j,d,i,h)*T(j,d,i+2,k); b=T(j,d,i+1,min(h+1,k))*T(j,d,i+1,max(h+1,k)-1); count+=1
     if a>b and len(fail)<12: fail.append([j,d,i,h,k,a,b])
o=dict(checks=count,failures=fail); Path(\"evidence/markov-af6200bf/shifted-probe.json\").write_text(json.dumps(o,indent=2)); print(o)'"

